(() => {
  if (window.__pcGhMdCopyInit) return;
  window.__pcGhMdCopyInit = true;

  function showToast(text) {
    const el = document.createElement('div');
    el.textContent = text;
    el.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:2147483647;padding:8px 14px;border-radius:8px;background:#1C1917;color:#FAF8F5;font:500 12.5px/1.4 system-ui,sans-serif;box-shadow:0 8px 24px rgba(0,0,0,.22)';
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 1600);
  }

  window.addEventListener('keydown', (e) => {
    if (!(e.altKey && e.shiftKey && e.key.toLowerCase() === 'c')) return;
    e.preventDefault();
    const cleanTitle = document.title.replace(/\s+by\s+[^·]+·.*$/, '').replace(/\s*·\s*GitHub$/, '').trim();
    const md = `[${cleanTitle}](${location.href})`;
    navigator.clipboard.writeText(md).then(() => showToast('Copied Markdown link')).catch(() => {});
  });
})();

